    func getNewsForDemographics(demographics: [String]) -> String {
        // Get news articles from reliable sources based on demographics
        let newsArticles = [
            "Global warming is a serious issue that requires immediate action to mitigate its effects on the environment and human health.",
            "The tax reform proposal is a complex and nuanced issue that requires careful consideration of the potential benefits and drawbacks for all stakeholders.",
            "The benefits of tax reform include increased economic growth, job creation, and a more equitable distribution of wealth, while the drawbacks include potential challenges to social safety nets and the risk of unintended consequences."
        ]

        // Filter news articles based on demographics
        var filteredNewsArticles: [String] = []
        for article in newsArticles {
            // Use demographic-specific criteria to filter news articles
            if demographics.contains("environment") {
                filteredNewsArticles.append(article)
            } else if demographics.contains("economics") {
                filteredNewsArticles.append(article)
            } else if demographics.contains("safety") {
                filteredNewsArticles.append(article)
            }
        }

        return filteredNewsArticles.joined(separator: "\n")
    }
}
